SELECT c.CustomerID, o.SalesOrderID
FROM Sales.Customer AS c
JOIN Sales.SalesOrderHeader AS o ON o.CustomerID = c.CustomerID;

SELECT c.CustomerID, o.SalesOrderID
FROM Sales.Customer AS c
LEFT JOIN Sales.SalesOrderHeader AS o ON o.CustomerID = c.CustomerID;

SELECT e.Name AS Employee, m.Name AS Manager
FROM dbo.Employee AS e
LEFT JOIN dbo.Employee AS m ON e.ManagerId = m.EmployeeId;
